s=s.replace("localStorage.setItem(serviceReleasePreflightStorage(c),JSON.stringify(h));serviceReleasePreflightBusy=true;", "try{localStorage.setItem(serviceReleasePreflightStorage(c),JSON.stringify(h));if(JSON.stringify(serviceReleasePreflightHandle(c))!==JSON.stringify(h))throw Error();}catch(e){$('service-release-preflight-status').textContent='无法保存原请求恢复引用，尚未发送预检记录。';return;}serviceReleasePreflightBusy=true;",1)
